  const { DocumentRepository: R } = require('../.build/repository');
  const { DocumentService: S } = require('../.build/service');
  const mk = (docs) => new R(docs);
  const base = () => [
    { id: 'own', tenant: 'a', owner: 'e', deleted: false, archived: false },
    { id: 'other', tenant: 'a', owner: 'x', deleted: false, archived: false },
    { id: 'del', tenant: 'a', owner: 'e', deleted: true, archived: false },
    { id: 'foreign', tenant: 'b', owner: 'e', deleted: false, archived: false },
    { id: 'arch', tenant: 'a', owner: 'x', deleted: false, archived: true },
  ];
  const admin = { tenant: 'a', user: 'adm', role: 'admin' };
  const editor = { tenant: 'a', user: 'e', role: 'editor' };
  const viewer = { tenant: 'a', user: 'e', role: 'viewer' };
  // not found for missing/deleted/foreign, even for admin
  for (const id of ['nope', 'del', 'foreign']) {
    const r = mk(base()); const s = new S(r);
    assert.throws(() => s.archive(admin, id), { message: 'not found' });
    assert.deepEqual(r.audit, []);
  }
  // viewer never allowed
  { const r = mk(base()); assert.throws(() => new S(r).archive(viewer, 'own'), { message: 'forbidden' }); assert.equal(r.documents[0].archived, false); assert.deepEqual(r.audit, []); }
  // editor only own
  { const r = mk(base()); assert.throws(() => new S(r).archive(editor, 'other'), { message: 'forbidden' }); assert.deepEqual(r.audit, []); }
  { const r = mk(base()); new S(r).archive(editor, 'own'); assert.equal(r.documents[0].archived, true); assert.deepEqual(r.audit, [{ actor: 'e', document: 'own' }]); }
  // admin any visible
  { const r = mk(base()); new S(r).archive(admin, 'other'); assert.deepEqual(r.audit, [{ actor: 'adm', document: 'other' }]); }
  // already archived: forbidden still enforced, no-op for permitted
  { const r = mk(base()); assert.throws(() => new S(r).archive(viewer, 'arch'), { message: 'forbidden' }); assert.deepEqual(r.audit, []); }
  { const r = mk(base()); new S(r).archive(admin, 'arch'); assert.deepEqual(r.audit, []); }
  { const r = mk(base()); assert.throws(() => new S(r).archive(editor, 'arch'), { message: 'forbidden' }); assert.deepEqual(r.audit, []); }
}
